    const MOD_NAME = "EBC";
    const MOD_VERSION = "3.3.7";
    const IS_DEV_BUILD = true; // true on dev branch, false on master
    let noticeShown = false;
    // Members already recorded in "people met" this session — avoids redundant server syncs
